def read(p):return json.loads(p.read_text(encoding='utf8'))
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def change(path,edit):
    p=ROOT/path;raw=p.read_bytes();old=raw.decode('utf8');crlf='\r\n' in old;text=edit(old.replace('\r\n','\n'));p.write_bytes(text.replace('\n','\r\n' if crlf else '\n').encode('utf8'))
